import sys,json,hashlib,collections,array,math,os
from pathlib import Path
import ijson

def digest(path):
 h=hashlib.sha256()
 with open(path,'rb')as f:
  for block in iter(lambda:f.read(1048576),b''):h.update(block)
 return {'path':str(Path(path).resolve()),'sha256':h.hexdigest(),'bytes':os.path.getsize(path)}

path,out=sys.argv[1:]
with open(path,'rb')as f:meta=next(ijson.items(f,'snapshot'))
nf=meta['meta']['node_fields'];ef=meta['meta']['edge_fields'];nw=len(nf);ew=len(ef)
nt=meta['meta']['node_types'][0];et=meta['meta']['edge_types'][0]
nodes=array.array('Q');edges=array.array('Q');strings=[]
with open(path,'rb')as f:
 for prefix,event,value in ijson.parse(f):
  if prefix=='nodes.item'and event=='number':nodes.append(value)
  elif prefix=='edges.item'and event=='number':edges.append(value)
  elif prefix=='strings.item'and event=='string':strings.append(value)
n=meta['node_count'];assert len(nodes)==n*nw and len(edges)==meta['edge_count']*ew
ix={k:nf.index(k)for k in nf};ex={k:ef.index(k)for k in ef}
types=nodes[ix['type']::nw];names=nodes[ix['name']::nw];sizes=nodes[ix['self_size']::nw];counts=nodes[ix['edge_count']::nw]
offsets=array.array('Q',[0]);running=0
for count in counts:running+=count*ew;offsets.append(running)
assert running==len(edges)
property_type=et.index('property');hidden_type=et.index('hidden');internal_type=et.index('internal');number_type=nt.index('number');string_type=nt.index('string');object_type=nt.index('object')
value_name=strings.index('value');dollar=strings.index('$')
number_values=array.array('q',[-1])*n;number_counts=collections.Counter();number_ranges={};missing=collections.Counter()
def classify(text):
 try:value=float(text)
 except ValueError:return 'unparsed'
 if not math.isfinite(value):return 'nonfinite'
 if not value.is_integer():return 'fractional'
 value=int(value)
 if value < -2147483648:return 'below_signed32'
 if value < 0:return 'signed32_negative'
 if value <=2147483647:return 'signed32_nonnegative'
 if value <=4294967295:return 'u32_high_bit_set'
 return 'above_u32'
for node in range(n):
 if types[node]!=number_type:continue
 label=strings[names[node]];number_counts[label]+=1
 for off in range(offsets[node],offsets[node+1],ew):
  if edges[off+ex['type']]==internal_type and edges[off+ex['name_or_index']]==value_name:
   target=edges[off+ex['to_node']]//nw
   if types[target]==string_type:number_values[node]=names[target]
 if number_values[node]<0:missing[label]+=1;continue
 number_ranges.setdefault(label,collections.Counter())[classify(strings[number_values[node]])]+=1
rows={};object_counts=collections.Counter();numeric_examples=[]
def add(tag,kind,field,target,property_aliases):
 key=(tag,kind,field,strings[names[target]])
 row=rows.setdefault(key,{'tag':tag,'edgeKind':kind,'field':field,'targetNumericKind':strings[names[target]],'references':0,'classCounts':collections.Counter(),'minFinite':None,'maxFinite':None,'exampleValueStrings':[],'sameTargetPropertyAliases':collections.Counter()})
 row['references']+=1
 v=number_values[target]
 if v<0:row['classCounts']['missing_value']+=1;return
 text=strings[v];row['classCounts'][classify(text)]+=1
 try:
  value=float(text)
  if math.isfinite(value):
   value=int(value)if value.is_integer()else value
   row['minFinite']=value if row['minFinite']is None else min(value,row['minFinite'])
   row['maxFinite']=value if row['maxFinite']is None else max(value,row['maxFinite'])
 except ValueError:pass
 if len(row['exampleValueStrings'])<8 and text not in row['exampleValueStrings']:row['exampleValueStrings'].append(text)
 for alias in property_aliases:row['sameTargetPropertyAliases'][alias]+=1
for node in range(n):
 if types[node]!=object_type:continue
 tag=None
 for off in range(offsets[node],offsets[node+1],ew):
  if edges[off+ex['type']]==property_type and edges[off+ex['name_or_index']]==dollar:
   target=edges[off+ex['to_node']]//nw
   if types[target]==string_type:tag=strings[names[target]]
   break
 if tag is None:continue
 object_counts[tag]+=1;number_edges=[];aliases={}
 for off in range(offsets[node],offsets[node+1],ew):
  target=edges[off+ex['to_node']]//nw
  if types[target]!=number_type:continue
  kind=edges[off+ex['type']];field=edges[off+ex['name_or_index']]
  field=str(field)if kind in[et.index('element'),hidden_type]else strings[field]
  if kind==property_type:aliases.setdefault(target,[]).append(field)
  number_edges.append((kind,field,target))
 for kind,field,target in number_edges:add(tag,et[kind],field,target,aliases.get(target,[])if kind==hidden_type else [])
 if number_edges and len(numeric_examples)<6:numeric_examples.append({'tag':tag,'numbers':[{'edgeKind':et[kind],'field':field,'numericKind':strings[names[target]],'value':strings[number_values[target]]if number_values[target]>=0 else None}for kind,field,target in number_edges]})
ordered=sorted(rows.values(),key=lambda r:(-r['references'],r['tag'],r['edgeKind'],r['field']))
result={'schemaVersion':1,'diagnosticOnly':True,'scope':'Numeric value/owner references in snapshot. Smi/artificial nodes are NOT allocated objects; HeapNumber node identity/type is not itself proof of allocator traffic, in-object layout or causal boxing. Hidden/property views may overlap; do not add rows or call them exclusive retained bytes. Snapshot induces GC and is not peak-memory evidence.','snapshot':digest(path),'nodeCount':n,'edgeCount':meta['edge_count'],'numberNodeLabels':dict(number_counts),'numericClassesByNodeLabel':{k:dict(v)for k,v in number_ranges.items()},'missingValuesByNodeLabel':dict(missing),'taggedObjectCounts':dict(object_counts),'numericFieldRows':ordered,'examples':numeric_examples}
Path(out).write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps({'output':out,'nodeCount':n,'numberNodeLabels':result['numberNodeLabels'],'numericClassesByNodeLabel':result['numericClassesByNodeLabel'],'topNumericFieldRows':ordered[:24]},indent=2))
